namespace ContextHub.Authentication.Application.Dtos.Users;

/// <summary>
/// Carries credential proof without allowing the caller to select another account or logging an autogenerated record value.
/// </summary>
/// <param name="currentPassword">The signed-in account's current password.</param>
/// <param name="newPassword">The replacement password validated by native Identity policy.</param>
public sealed class ChangePasswordRequestDto(string currentPassword, string newPassword)
{
    /// <summary>
    /// Gets the current credential proof, which must be masked before diagnostics.
    /// </summary>
    /// <example>ExampleOnly!2026</example>
    public string CurrentPassword { get; } = currentPassword;

    /// <summary>
    /// Gets the replacement credential, which must be masked before diagnostics.
    /// </summary>
    /// <example>ReplacementOnly!2026</example>
    public string NewPassword { get; } = newPassword;
}
